sparql_tries.sparql:
SELECT DISTINCT ?modelYear WHERE {
  ?camp rc:campaignNumber "26V430000" ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?modelYear .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?modelYear

SELECT DISTINCT ?componentName WHERE {
  ?campaign rc:campaignNumber "10V388000" ;
            rc:affectsComponent ?component .
  ?component rc:name ?componentName .
}
ORDER BY ?componentName

SELECT ?reportReceivedDate WHERE {
  ?campaign rc:campaignNumber "23V651000" ;
            rc:reportReceivedDate ?reportReceivedDate .
}

SELECT ?affected WHERE {
  ?campaign rc:campaignNumber "26V430000" ;
            rc:potentiallyAffected ?affected .
}

SELECT DISTINCT ?campNo ?makeName WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campNo ;
     rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER (UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?campNo

SELECT ?campaignNumber ?init WHERE {
  ?c a rc:RecallCampaign ;
     rc:initiatedBy ?init ;
     rc:campaignNumber ?campaignNumber .
  FILTER(CONTAINS(UCASE(STR(?init)), "OVSC"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?reportDate WHERE {
  ?camp a rc:RecallCampaign ;
        rc:campaignNumber ?campaignNumber ;
        rc:reportReceivedDate ?reportDate ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(UCASE(STR(?makeName)) = "HYUNDAI")
  FILTER(UCASE(STR(?modelName)) = "PALISADE")
  FILTER(YEAR(?reportDate) = 2024)
}
ORDER BY ?reportDate

SELECT ?compName (COUNT(DISTINCT ?c) AS ?campaigns) WHERE {
  ?c a rc:RecallCampaign ;
     rc:affectsComponent ?comp ;
     rc:affects ?v .
  ?comp rc:name ?compName .
  FILTER NOT EXISTS { ?child skos:broader ?comp . }
  ?v rc:ofModel/rc:ofMake/rc:name ?mk .
  FILTER(?mk IN ("HYUNDAI", "KIA"))
  FILTER EXISTS {
    ?h1 a rc:RecallCampaign ;
        rc:affectsComponent ?comp ;
        rc:affects/rc:ofModel/rc:ofMake/rc:name "HYUNDAI" .
  }
  FILTER EXISTS {
    ?k1 a rc:RecallCampaign ;
        rc:affectsComponent ?comp ;
        rc:affects/rc:ofModel/rc:ofMake/rc:name "KIA" .
  }
}
GROUP BY ?compName
ORDER BY DESC(?campaigns) ?compName
LIMIT 1

SELECT ?campNo (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campNo ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
}
GROUP BY ?c ?campNo
HAVING (COUNT(DISTINCT UCASE(STR(?makeName))) > 1)
ORDER BY DESC(COUNT(DISTINCT UCASE(STR(?makeName)))) ?campNo

SELECT DISTINCT ?campaignNumber WHERE {
  ?camp a rc:RecallCampaign ;
        rc:campaignNumber ?campaignNumber ;
        rc:affects ?variant .
  ?variant rc:modelYear ?modelYear ;
           rc:ofModel ?model .
  ?model rc:name "SANTA FE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER(STR(?modelYear) = "2021")
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?genesisModel WHERE {
  ?kiaCamp a rc:RecallCampaign ;
           rc:affects ?kiaVariant ;
           rc:affectsComponent ?comp .
  ?kiaVariant rc:ofModel ?kiaModel .
  ?kiaModel rc:name "TELLURIDE" ;
            rc:ofMake ?kiaMake .
  ?kiaMake rc:name "KIA" .

  ?genCamp a rc:RecallCampaign ;
           rc:affects ?genVariant ;
           rc:affectsComponent ?comp .
  ?genVariant rc:ofModel ?genModelRes .
  ?genModelRes rc:name ?genesisModel ;
               rc:ofMake ?genMake .
  ?genMake rc:name "GENESIS" .
}
ORDER BY ?genesisModel

SELECT ?modelName (COUNT(DISTINCT ?c) AS ?campaigns)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name ?modelName .
}
GROUP BY ?m ?modelName
ORDER BY DESC(?campaigns) ?modelName

SELECT (COUNT(DISTINCT ?c) AS ?campaignCount) WHERE {
  ?c rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?d) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:affectsComponent ?comp ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  ?top a rc:Component .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?modelCount)

SELECT ?campaignNumber ?potentiallyAffected WHERE {
  ?c a rc:RecallCampaign ;
     rc:parkOutside true ;
     rc:campaignNumber ?campaignNumber ;
     rc:potentiallyAffected ?potentiallyAffected .
}
ORDER BY DESC(?potentiallyAffected)
LIMIT 1

SELECT (COUNT(DISTINCT ?campaign) AS ?odiCampaignCount)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:initiatedBy ?initiator .
  FILTER(CONTAINS(UCASE(STR(?initiator)), "ODI"))
}

SELECT ?topName (COUNT(DISTINCT ?camp) AS ?campaigns) WHERE {
  ?make a rc:Make ;
        rc:name "GENESIS" .
  ?model rc:ofMake ?make .
  ?variant rc:ofModel ?model .
  ?camp rc:affects ?variant ;
        rc:affectsComponent ?comp .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?campaigns) ?topName

SELECT (COUNT(DISTINCT ?year) AS ?yearCount) WHERE {
  ?make rc:name "HYUNDAI" .
  ?model rc:ofMake ?make ;
         rc:name "SONATA" .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?campaign rc:affects ?variant .
}

SELECT ?year (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(?mkName IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?n)
LIMIT 1

SELECT DISTINCT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?c rc:defectSummary ?d }
  OPTIONAL { ?c rc:rootCause ?r }
  OPTIONAL { ?c rc:consequenceSummary ?k }
  BIND(LCASE(CONCAT(COALESCE(?d, ""), " ", COALESCE(?r, ""), " ", COALESCE(?k, ""))) AS ?txt)
  FILTER(CONTAINS(?txt, "hydrogen") && (CONTAINS(?txt, "leak") || CONTAINS(?txt, "detect") || CONTAINS(?txt, "sensor")))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?comp rc:name ?cname .
  FILTER(REGEX(?cname, "CHARGING|ICCU", "i"))
  ?sub skos:broader* ?comp .
  ?camp rc:affectsComponent ?sub ;
        rc:campaignNumber ?campaignNumber .
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?rc a rc:RecallCampaign ;
      rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?rc rc:affectsComponent ?comp . ?comp rc:name ?compName . }
  OPTIONAL { ?rc rc:defectSummary ?defect . }
  OPTIONAL { ?rc rc:rootCause ?root . }
  OPTIONAL { ?rc rc:consequenceSummary ?conseq . }
  BIND(UCASE(CONCAT(COALESCE(?compName, ""), " ", COALESCE(?defect, ""), " ", COALESCE(?root, ""), " ", COALESCE(?conseq, ""))) AS ?text)
  FILTER(CONTAINS(?text, "TRAIL") || CONTAINS(?text, "TOW") || CONTAINS(?text, "HITCH"))
  FILTER(CONTAINS(?text, "WATER") || CONTAINS(?text, "MOISTURE"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:defectSummary ?d .
  FILTER(REGEX(?d, "rod", "i") && REGEX(?d, "bearing", "i") && REGEX(?d, "wear", "i"))
}
ORDER BY ?campaignNumber
